import{_ as e,o as i,c as n,a as t}from"./app.b21076ea.js";var a="/aktivitaeten/BDM-2026-08/00_08-2026.jpg",r="/aktivitaeten/BDM-2026-08/01_08-2026.jpg",s="/aktivitaeten/BDM-2026-08/02_08-2026.jpg",d="/aktivitaeten/BDM-2026-08/03_08-2026.jpg",l="/aktivitaeten/BDM-2026-08/04_08-2026.jpg",m="/aktivitaeten/BDM-2026-08/05_08-2026.jpg",u="/aktivitaeten/BDM-2026-08/06_08-2026.jpg",g="/aktivitaeten/BDM-2026-08/07_08-2026.jpg",o="/aktivitaeten/BDM-2026-08/08_08-2026.jpg",h="/aktivitaeten/BDM-2026-08/09_08-2026.jpg",c="/aktivitaeten/BDM-2026-08/10_08-2026.jpg",p="/aktivitaeten/BDM-2026-08/11_08-2026.jpg",_="/aktivitaeten/BDM-2026-08/12_08-2026.jpg",v="/aktivitaeten/BDM-2026-08/13_08-2026.jpg",k="/aktivitaeten/BDM-2026-08/14_08-2026.jpg",B="/aktivitaeten/BDM-2026-08/15_08-2026.jpg",M="/aktivitaeten/BDM-2026-08/16_08-2026.jpg",D="/aktivitaeten/BDM-2026-08/17_08-2026.jpg",b="/aktivitaeten/BDM-2026-08/18_08-2026.jpg",f="/aktivitaeten/BDM-2026-08/19_08-2026.jpg",w="/aktivitaeten/BDM-2026-08/20_08-2026.jpg",z="/aktivitaeten/BDM-2026-08/21_08-2026.jpg",S="/aktivitaeten/BDM-2026-08/22_08-2026.jpg",A="/aktivitaeten/BDM-2026-08/23_08-2026.jpg",j="/aktivitaeten/BDM-2026-08/24_08-2026.jpg",F="/aktivitaeten/BDM-2026-08/25_08-2026.jpg",W="/aktivitaeten/BDM-2026-08/26_08-2026.jpg",E="/aktivitaeten/BDM-2026-08/27_08-2026.jpg",T="/aktivitaeten/BDM-2026-08/28_08-2026.jpg",H="/aktivitaeten/BDM-2026-08/29_08-2026.jpg",P="/aktivitaeten/BDM-2026-08/30_08-2026.jpg",R="/aktivitaeten/BDM-2026-08/31_08-2026.jpg",N="/aktivitaeten/BDM-2026-08/32_08-2026.jpg",K="/aktivitaeten/BDM-2026-08/33_08-2026.jpg",O="/aktivitaeten/BDM-2026-08/34_08-2026.jpg",C="/aktivitaeten/BDM-2026-08/35_08-2026.jpg",I="/aktivitaeten/BDM-2026-08/36_08-2026.jpg",Q="/aktivitaeten/BDM-2026-08/37_08-2026.jpg",U="/aktivitaeten/BDM-2026-08/38_08-2026.jpg",V="/aktivitaeten/BDM-2026-08/39_08-2026.jpg",L="/aktivitaeten/BDM-2026-08/40_08-2026.jpg",G="/aktivitaeten/BDM-2026-08/41_08-2026.jpg",X="/aktivitaeten/BDM-2026-08/42_08-2026.jpg",y="/aktivitaeten/BDM-2026-08/43_08-2026.jpg",J="/aktivitaeten/BDM-2026-08/44_08-2026.jpg",x="/aktivitaeten/BDM-2026-08/45_08-2026.jpg",Z="/aktivitaeten/BDM-2026-08/46_08-2026.jpg",q="/aktivitaeten/BDM-2026-08/47_08-2026.jpg",Y="/aktivitaeten/BDM-2026-08/48_08-2026.jpg",$="/aktivitaeten/BDM-2026-08/49_08-2026.jpg",ee="/aktivitaeten/BDM-2026-08/50_08-2026.jpg",ie="/aktivitaeten/BDM-2026-08/51_08-2026.jpg",ne="/aktivitaeten/BDM-2026-08/52_08-2026.jpg",te="/aktivitaeten/BDM-2026-08/53_08-2026.jpg",ae="/aktivitaeten/BDM-2026-08/54_08-2026.jpg",re="/aktivitaeten/BDM-2026-08/55_08-2026.jpg",se="/aktivitaeten/BDM-2026-08/56_08-2026.jpg",de="/aktivitaeten/BDM-2026-08/57_08-2026.jpg",le="/aktivitaeten/BDM-2026-08/58_08-2026.jpg",me="/aktivitaeten/BDM-2026-08/59_08-2026.jpg",ue="/aktivitaeten/BDM-2026-08/60_08-2026.jpg";const ge={},oe=t('<h1 id="bilder-des-monats-august-2026" tabindex="-1"><a class="header-anchor" href="#bilder-des-monats-august-2026" aria-hidden="true">#</a> Bilder des Monats August 2026</h1><hr><p>DL7DL im Urlaub. Den Aussichtsturm f\xFCr den FT8 Activity Day auf 2m genutzt. https://ft8activity.eu https://maps.app.goo.gl/9wdMWT98rMvNJbAZA?g_st=ic</p><p><img src="'+a+'" alt="Bilder des Monats"><img src="'+r+'" alt="Bilder des Monats"><img src="'+s+'" alt="Bilder des Monats"><img src="'+d+'" alt="Bilder des Monats"></p><hr><p>W\xE4hrend des Urlaubes auf der Insel F\xF6hr heute mal den Nationalpark Nordfriesisches Wattenmeer DE-0127 aktiviert. Morgens um 7 Uhr war es noch menschenleer am Strand und so konnte ich ungest\xF6rt an der Kante zum Wasser die Vertikal aufbauen. Die Bedingungen waren nicht so optimal und es war etwas z\xE4h. Aber immerhin kamen in etwas \xFCber einer Stunde 13 QSOs in FT8/FT4 auf 40 und 20 Meter zu Stande. (Thorsten DG4HZ)</p><p><img src="'+l+'" alt="Bilder des Monats"><img src="'+m+'" alt="Bilder des Monats"><img src="'+u+'" alt="Bilder des Monats"><img src="'+g+'" alt="Bilder des Monats"></p><hr><p>Als Vorbereitung f\xFCr den Urlaub sollte heute mal die kleine QRP Ausr\xFCstung getestet werden. Also ging es mit dem FT-817 und Fuchskreis-Antenne in den Hauspark. Fast nur 40m gemacht, ein wenig Katzenbilder auf SSTV und dann SSB. Mit 5 W gelangen problemlos 19 QSOs, auch einige DF2DF dabei. 73 DF9HC</p><p><img src="'+o+'" alt="Bilder des Monats"><img src="'+h+'" alt="Bilder des Monats"><img src="'+c+'" alt="Bilder des Monats"></p><hr><p>Heute Vormittag habe ich (HB9FGU) am Aare-Ufer in JN37re ein bisschen Betrieb auf Kurzwelle gemacht. Hier ein paar fotografische Eindr\xFCcke:</p><p><img src="'+p+'" alt="Bilder des Monats"><img src="'+_+'" alt="Bilder des Monats"><img src="'+v+'" alt="Bilder des Monats"><img src="'+k+'" alt="Bilder des Monats"><img src="'+B+'" alt="Bilder des Monats"></p><hr><p>Nachdem Haiko DF9HC im Drau\xDFenfunker-Discord angek\xFCndigt hatte, QRP-Betrieb machen zu wollen, hat mich das motiviert mein FT-817ND einzupacken und es ihm gleich zu tun. Bei bestem Wetter ging es in den S\xFCderelbpark, der Teil der POTA-Referenz DE-0138 ist. In der Regel nutze ich f\xFCr Aktivierungen mein FT-891 und die bekannte Drau\xDFenfunker-Vertical, aber bei QRP-Betrieb wollte ich eine effizientere Antenne nutzen. Also habe ich meinen Linked Dipole und einen Mast mitgenommen, in der Hoffnung, dass er schon irgendwo hinpassen wird. Beim Aufbau fiel mir auf, dass ich zwar Heringe f\xFCr die Mastabspannung, aber nicht f\xFCr die Dipolenden dabei hatte. Da traf es sich gut, dass der Platz eh zu knapp gewesen w\xE4re, die Dipolenden mit Seilen abzuspannen. Also habe ich das eine Ende um einen Pfahl geschlungen und mit meinem Vertical-Erdspie\xDF einen Hering improvisiert. Das andere Ende habe ich um einen Baum gebunden. Da ich mir unsicher war, ob der leicht ver\xE4ndere Dipolwinkel Probleme verursacht, habe ich die Antenne mit dem NanoNVA gemessen. Da es mir prim\xE4r darum ging mein Funkger\xE4t zu sch\xFCtzen, habe ich nur das VSWR gemessen: Das Minimum von etwa 1,1 war auf 40 m im CW-Bereich zu finden. Und so gingen 26 QSOs in CW und 5 QSOs in SSB \u2013 unter Anderem mit Haiko und vielen weiteren Drau\xDFenfunkern \u2013 ins Log. (Haupts\xE4chlich auf 40 m und ein Bruchteil auf 20 m.) Nach langer Amateurfunk-Abstinenz hat es viel Spa\xDF gemacht wieder aktiv zu werden. Und es hat sehr viel Spa\xDF gemacht, mal wieder 72 statt 73 zu geben.</p><p>(Peter DL6PL)</p><p><img src="'+M+'" alt="Bilder des Monats"><img src="'+D+'" alt="Bilder des Monats"><img src="'+b+'" alt="Bilder des Monats"><img src="'+f+'" alt="Bilder des Monats"><img src="'+w+'" alt="Bilder des Monats"><img src="'+z+'" alt="Bilder des Monats"></p><hr><p>In der letzten Juli Woche fand in OE2 in Wagrain das YOTA Summer Camp der IARU-Region 1 statt. Im Gro\xDFen und Ganzen war die Struktur immer etwas bauen, was bei einem sp\xE4teren Programmpunkt ben\xF6tigt wird. So wurden zu Beginn die 70cm Draussenfuchs-Yagi (https://draussenfuchs.de/#technik) und eine End-Fed-Antenne (mit Kabeltrommel) von OE1WBS f\xFCr Kurzwelle sowie ein BNC-Kabel gebaut. Danach wurden QMX-Transceiver gebaut, welche mit der Kurzwellenantenne und dem BNC-Kabel verwendet werden k\xF6nnen.</p><p>In der Woche waren wir mit den Teilnehmern in der Burg Hohenwerfen und der Eisriesenwelt. Die Burg z\xE4hlte zum World Castle Award (WCA) und kann daher aktiviert werden. Leider waren die B\xE4nder an dem Tag zu, sodass man auf der Burg leider nichts h\xF6ren konnte, jedoch waren alle B\xE4nder frei von St\xF6rungen.</p><p>Ein weiteres Highlight war die SOTA-Aktivierung von zwei Bergen parallel. Da viele Teilnehmer ein Handfunkger\xE4t dabei hatten und einige QMX+ Transceiver zur Verf\xFCgung standen, konnten schon alleine durch die Anzahl an Teilnehmern eine gro\xDFe Anzahl an S2S-Verbindungen hergestellt werden - zus\xE4tzlich zu den Verbindungen, die wir zus\xE4tzlich mit zuf\xE4lligen Stationen geschafft haben. Manche Funkamateure hatten auch gr\xF6\xDFere und damit vielseitigere Transceiver mit, die auch den Teilnehmern f\xFCr den Betrieb zur Verf\xFCgung standen. So wurden die Berge auch auf 2m in CW aktiviert. Als Modes kamen mindestens SSB, FM, CW und D-STAR zum Einsatz.</p><p>Ende der Woche wurde noch ein ARDF-Wettbewerb auf 80m veranstaltet und ein Versuch unternommen, die ISS als Repeater zu nutzen. Dies scheiterte leider aufgrund des Umstandes, dass der ISS-Repeater leider belegt war.</p><p>Es gab in der Woche ebenfalls einen geplanten ISS-Kontakt, bei dem die Jugendlichen einer Astronautin fragen stellen konnten.</p><p>Wer Interesse hat, sollte sich diesbez\xFCglich beim IARU-Mitgliedsverein f\xFCr n\xE4chstes Jahr anmelden!</p><p>Fotos gibt es hier: https://g.ham-yota.com/gallery/B3oN-38QxHkb-2ZImRs66AFd</p><p>(Fabian OE9LTX)</p><p><img src="'+S+'" alt="Bilder des Monats"><img src="'+A+'" alt="Bilder des Monats"><img src="'+j+'" alt="Bilder des Monats"><img src="'+F+'" alt="Bilder des Monats"><img src="'+W+'" alt="Bilder des Monats"><img src="'+E+'" alt="Bilder des Monats"><img src="'+T+'" alt="Bilder des Monats"><img src="'+H+'" alt="Bilder des Monats"><img src="'+P+'" alt="Bilder des Monats"></p><hr><p>Am letzten Abend in Bremen noch eine spontane Aktivierung direkt an der Weser im Stadtzentrum gleich in der N\xE4he unserer Ferienwohnung. Ich hab nicht viel erwartet, keine besondere Antenne, relativ viel QRM in der Stadt aber war \xFCberrascht wie gut es lief. 34 QSOs in ca. 40 Minuten, viele Stationen mit 10 bis 30 dB \xFCber S9. 73 de DF9HC</p><p><img src="'+R+'" alt="Bilder des Monats"><img src="'+N+'" alt="Bilder des Monats"><img src="'+K+'" alt="Bilder des Monats"></p><hr><p>DC1TC: Ich bin endlich mal wieder raus in einen POTA-Park gekommen. Es war der Bayerische Wald Naturpark (DE-0011) mit den Trails Deutsche Limes-Stra\xDFe Radweg (DE-0941) sowie Pilgerweg Via Nova (DE-0590) bei Niederalteich dran. Die Donau f\xFChrt zur Zeit echt wenig Wasser, sogar der niedrigste Pegel war trocken und die F\xE4hre au\xDFer Betrieb.</p><p><img src="'+O+'" alt="Bilder des Monats"><img src="'+C+'" alt="Bilder des Monats"></p><hr><p>DA6MAX hat DE-1274 (Wetterau Bird Sanctuary, DE-HE) aktiviert.</p><p>Heute ging es zum zweiten Mal in den ganz frischen POTA-Park DE-1274 (Wetterau Bird Sanctuary) \u2013 eine Zusammenfassung mehrerer Vogelschutzgebiete in der Region, von denen eins gl\xFCcklicherweise direkt vor meiner Haust\xFCr liegt!</p><p>Nachdem der Spot gestern am Parkrand noch nicht ganz optimal war, habe ich heute meinen absoluten Komfort-Spot gefunden: Nur ca. 2 km mit dem Fahrrad von zu Hause entfernt, direkt am R4 Nidda-Radweg an der Br\xFCcke zwischen Nieder-W\xF6llstadt und Burggr\xE4fenrode.</p><p>Setup &amp; Aktivit\xE4t: Antenne: Vertical-Antenne auf dem gem\xE4hten Feld hinter der Bank aufgebaut. Es g\xE4be dort aber auch super M\xF6glichkeiten, eine EFHW zu spannen \u2013 eventuell beim n\xE4chsten Mal sogar quer \xFCber die Nidda! B\xE4nder &amp; Modi: Das 15m-Band lief heute fantastisch! Es hat besonders gefreut, dass SSB dominiert hat. 17 QSOs in SSB und 3 in FT8 ergeben insgesamt 20 QSOs in 12 DXCC-L\xE4ndern. Viele nette Kontakte mit kurzem Kl\xF6nschnack \u2013 genau so macht Drau\xDFenfunken richtig Spa\xDF! Ein spezieller Dank geht an DA6XJ als treuen Hunter aus der Region f\xFCr die Verbindung \xFCber die Bodenwelle!</p><p>73, DA6MAX</p><p><img src="'+I+'" alt="Bilder des Monats"><img src="'+Q+'" alt="Bilder des Monats"><img src="'+U+'" alt="Bilder des Monats"><img src="'+V+'" alt="Bilder des Monats"><img src="'+L+'" alt="Bilder des Monats"></p><hr><p>Im August habe ich beim Kreisjugendring Pinneberg verschiedene Ferienpass-Aktionen rund um Funkfuchssuche und Amateurfunk angeboten. Am letzten Tag der Sommerferien findet au\xDFerdem traditionell immer das Kinderspielfest auf dem Gel\xE4nde des KJR statt. Hier habe ich noch einmal die Funkfuchssuche auf dem Gel\xE4nde angeboten. Unz\xE4hlige Kinder haben zwischen 13 und 17 Uhr die f\xFCnf versteckten F\xFCchse auf dem Gel\xE4nde gesucht und gr\xF6\xDFtenteils auch gefunden. \u{1F609} Letztes Jahr waren sechs Ger\xE4te zum Suchen vorhanden und fast durchgehend ausgeliehen. Dieses Jahr habe ich auf neun Ger\xE4te aufgestockt und es war immer noch mit Wartezeiten zu rechnen, weil flei\xDFige Sucher unterwegs waren. Da muss wohl noch mal aufger\xFCstet werden... Auf jeden Fall werde ich auch 2027 wieder Aktionen rund um das Thema Funk anbieten. Harm, DK4HAA</p><p><img src="'+G+'" alt="Bilder des Monats"><img src="'+X+'" alt="Bilder des Monats"><img src="'+y+'" alt="Bilder des Monats"></p><hr><p>DA6MAX hat DE-1274 aktiviert!</p><p>Premiere gegl\xFCckt! Ich war heute zum allerersten Mal f\xFCr eine reine SSB-Aktivierung unterwegs - den Laptop habe ich bewusst zu Hause gelassen. Schauplatz des Geschehens war mein Homebase-Park direkt vor der Haust\xFCr (Wetterau Bird Sanctuary / DE-1274).</p><p>Setup: Keine Ablenkung, kein Schnickschnack \u2013 nur ich, mein Fahrrad, eine Decke mitten im Feld und der Vertical Dipol auf der Wiese.</p><p>Und was soll ich sagen? Die \xC4ther-G\xF6tter meinten es gut mit mir:</p><ul><li>DX-Alarm: 1 QSO in die USA und 2-mal r\xFCber nach Kanada gekurbelt!</li><li>Bodenwelle rockt: Auch heimatnah ging einiges Richtung Taunus und Vogelsberg.</li><li>DF-Danke-Shoutout: Ein riesiges Dankesch\xF6n an DK5UR und DA6XJ f\xFCr die QSOs \xFCber die Bodenwelle!</li></ul><p>Insgesamt standen am Ende 28 QSOs im Log (15m &amp; 10m Band). F\xFCr die erste reine SSB-Sitzung im Gras liegend absolut fantastisch!</p><p>An alle da drau\xDFen: Schnappt euch den Draht, schwingt euch aufs Rad und ab ins Feld !</p><p><img src="'+J+'" alt="Bilder des Monats"><img src="'+x+'" alt="Bilder des Monats"><img src="'+Z+'" alt="Bilder des Monats"><img src="'+q+'" alt="Bilder des Monats"><img src="'+Y+'" alt="Bilder des Monats"></p><hr><p>DK5CH und DB6NL: Heute haben wir mal die Gelegenheit genutzt im Park DE-0911 eine Bike-Pota-Aktion zu machen. CW only haben wir unterschiedliche Antennen und Tranciever getestet und verglichen. Trotz widriger Bandbedingungen kamen qrp 19 QSOs ins Log. Davon auch einige P2P und DF2DF-verbindungen.</p><p><img src="'+$+'" alt="Bilder des Monats"><img src="'+ee+'" alt="Bilder des Monats"><img src="'+ie+'" alt="Bilder des Monats"><img src="'+ne+'" alt="Bilder des Monats"><img src="'+te+'" alt="Bilder des Monats"></p><hr><p>Im diesj\xE4hrigen Sommerurlaub ging es mit dem Fahrrad und Sack und Pack entspannt auf dem Ostseeradweg von Stralsund entlang der Ostseek\xFCste mit dem Ziel polnische Grenze. Die liegt ja gl\xFCcklicherweise auf Usedom und ist somit feinstes POTA-Gebiet.</p><p>Und nat\xFCrlich musste ich die Chance zu nutzen und versuchen DE-0105 zu aktivieren. Da wir f\xFCr unsere zehn Tage Reise alles mit auf dem Rad hatten blieb nicht mehr viel Spiel f\xFCr gro\xDFes Afu-Equipment. Also hie\xDF es: QRP (mein erstes Mal), nur CW und das alles mit so viel Flexibilit\xE4t wie m\xF6glich und so wenig Fu\xDFabdruck wie n\xF6tig. Dabei raus gekommen ist ein Kit mit QMX plus Powerbank, ein 20m Dipol, eine 40m EFHW, ein 4m &quot;Mast&quot; und das n\xF6tige Zubeh\xF6r. Das Kit hatte ca. 1,1 Kg und fand in meiner Lenkertasche platz. Der Mast passte noch gut zwischen die Zelte und war damit nicht im Weg.</p><p>Auf Usedom angekommen konnte ich DE-0105 dreimal erfolgreich in CW aktivieren. Dabei hab ich sowohl den Dipol als auch die EFHW eingesetzt. Beide Antennen habe ich ungetestet noch vor dem Urlaub fix zusammengebaut. Nach der zweiten Aktivierung habe ich erschrocken festgestellt das nur 200m! von einem 5-fer entfernt war. Ich habe es schlicht nicht mitbekommen. Das konnte ich aber nicht auf mir sitzen lassen und habe das tags drauf noch mit der dritten Aktivierung korrigiert.</p><p>Im Summe fanden sich nach etwas einer Stunde immer so zwischen 10 und 15 QSOs im Log. Ich bin noch recht neu in der CW-Welt und damit war alles ein wenig holprig und ging nur mit viel Nachfragen. Aber alle OPs die mir geantwortet haben waren nett und sehr geduldig \u2013 Danke daf\xFCr! So macht das Spa\xDF.</p><p>R\xFCckwirkend kann ich zu meiner Wahl der Ausr\xFCstung sehr zufrieden. Ich hatte noch nie mit so wenig Leistung gesendet und ich kann f\xFCr mich sagen: QRP funktioniert f\xFCr mich. Es macht mir viel Spa\xDF mit wenig raus zu gehen und sein Gl\xFCck mit dem zu versuchen was man hat. Und das wird nicht das letzte Mal gewesen sein.</p><p>Felix, DL7LW</p><p><img src="'+ae+'" alt="Bilder des Monats"><img src="'+re+'" alt="Bilder des Monats"><img src="'+se+'" alt="Bilder des Monats"><img src="'+de+'" alt="Bilder des Monats"><img src="'+le+'" alt="Bilder des Monats"><img src="'+me+'" alt="Bilder des Monats"><img src="'+ue+'" alt="Bilder des Monats"></p>',63),he=[oe];function ce(pe,_e){return i(),n("div",null,he)}var ke=e(ge,[["render",ce],["__file","2026-08-30-Bilder-Des-Monats-August.html.vue"]]);export{ke as default};
